package com.retailflow.pos.staff;
import com.retailflow.pos.common.ApiResponse;import java.time.LocalDate;import org.springframework.format.annotation.DateTimeFormat;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1") @PreAuthorize("hasRole('OWNER')") public class StaffController{private final StaffService s;public StaffController(StaffService s){this.s=s;}@GetMapping("/staff")public ApiResponse<?>list(){return ApiResponse.ok(s.list());}@GetMapping("/staff/{id}")public ApiResponse<?>get(@PathVariable String id){return ApiResponse.ok(s.get(id));}@PostMapping("/staff")public ApiResponse<?>create(@RequestBody Staff v){return ApiResponse.ok(s.save(v));}@PutMapping("/staff/{id}")public ApiResponse<?>update(@PathVariable String id,@RequestBody Staff v){v.setId(id);return ApiResponse.ok(s.save(v));}@DeleteMapping("/staff/{id}")public ApiResponse<Void>delete(@PathVariable String id){s.delete(id);return ApiResponse.ok(null);}@GetMapping("/attendance")public ApiResponse<?>attendance(@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate date){return ApiResponse.ok(s.attendance(date));}@PostMapping("/attendance")public ApiResponse<?>attendanceCreate(@RequestBody AttendanceRecord v){return ApiResponse.ok(s.saveAttendance(v));}@PutMapping("/attendance/{id}")public ApiResponse<?>attendanceUpdate(@PathVariable String id,@RequestBody AttendanceRecord v){v.setId(id);return ApiResponse.ok(s.saveAttendance(v));}}
